// SQLite hands dates back as either an ISO string or epoch millis depending on
// how the row was written; both collapse to a plain YYYY-MM-DD here.
function toDay(value: string | number | null): string {
  if (value === null) return "";
  const date = new Date(typeof value === "number" ? value : Date.parse(value));
  return Number.isNaN(date.getTime()) ? "" : date.toISOString().slice(0, 10);
}

function toUser(row: UserRow): User {
  return {
    id: row.id,
    email: row.email,
    name: row.name?.trim() || row.email.split("@")[0],
    createdAt: toDay(row.createdAt),
  };
}

const SELECT = `select id, email, name, createdAt from "user"`;

function query<T>(run: () => T): T {
  try {
    return run();
  } catch (error) {
    if (error instanceof Error && /no such table/.test(error.message)) {
      throw new Error("Auth tables are missing — run `npm run db:migrate` first.");
    }
    throw error;
  }
}

export async function listUsers(): Promise<User[]> {
  const rows = query(
    () => db.prepare(`${SELECT} order by createdAt asc`).all() as UserRow[],
  );
  return rows.map(toUser);
}

export async function getUser(id: string): Promise<User | undefined> {
  const row = query(
    () => db.prepare(`${SELECT} where id = ?`).get(id) as UserRow | undefined,
  );
  return row && toUser(row);
}

/**
 * The signed-in user for the current request, or undefined when there is no
 * valid session cookie. Server components and route handlers only.
 */
export async function getCurrentUser(): Promise<User | undefined> {
  const session = await auth.api.getSession({ headers: await headers() });
  if (!session) return undefined;

  // Read through to the row so callers get the same shape as listUsers().
  return (
    (await getUser(session.user.id)) ?? {
      id: session.user.id,
      email: session.user.email,
      name: session.user.name?.trim() || session.user.email.split("@")[0],
      createdAt: toDay(
        session.user.createdAt instanceof Date
          ? session.user.createdAt.getTime()
          : session.user.createdAt,
      ),
    }
  );
}

/**
 * Same as getCurrentUser(), but for pages that must not render for anonymous
 * visitors: sends them to sign-in instead of returning undefined.
 */
export async function requireUser(returnTo = "/dashboard"): Promise<User> {
  const user = await getCurrentUser();
  if (!user) {
    const { redirect } = await import("next/navigation");
    redirect(`/sign-in?next=${encodeURIComponent(returnTo)}`);
  }
  return user;
}

